<?php
declare(strict_types=1);
require dirname(__DIR__,2).'/includes/bootstrap.php';require_permission('video_categories.manage');$pdo=db();
if(is_post()){verify_csrf();try{$name=trim((string)input('name'));$commission=(float)input('platform_commission_rate');$reward=(float)input('customer_reward_rate');if($name===''||$commission<0||$commission>100||$reward<0||$reward>100)throw new InvalidArgumentException('Enter a category name and rates between 0 and 100.');$slug='shop_'.trim(preg_replace('/[^a-z0-9]+/','_',strtolower($name)),'_').'_'.bin2hex(random_bytes(2));$pdo->prepare('INSERT INTO video_categories(name,slug,commission_type,platform_commission_rate,customer_reward_rate,character_asset_url,capacity_limit,status,created_by) VALUES(?,?,?,?,?, ?,500,"ACTIVE",?)')->execute([$name,$slug,strtoupper((string)input('commission_type','PERCENTAGE')),$commission,$reward,trim((string)input('icon_path'))?:null,admin()['id']]);$id=$pdo->lastInsertId();audit_log((int)admin()['id'],'CATEGORY_COMMISSION_CREATED','video_categories',(string)$id,null,['commission_rate'=>$commission,'reward_rate'=>$reward]);flash('success','Shop category created.');}catch(Throwable $e){flash('error',$e->getMessage());}redirect('/admin/categories/commission.php');}
$rows=$pdo->query('SELECT id,name,slug,character_asset_url,commission_type,platform_commission_rate,customer_reward_rate,status FROM video_categories ORDER BY name')->fetchAll();$pageTitle='Shop categories & commission';$pageSubtitle='Category icons, platform commission and customer cashback rules';require APP_ROOT.'/includes/header.php';
?><section class="vendor-hero"><h2>HUNTER WALLET ADMIN · ADD SHOP CATEGORY &amp; COMMISSION MANAGER</h2><span>Category name → icon → commission rate → customer reward → live directory</span></section><section class="panel"><h2>1. Add new shop category &amp; set commission rate</h2><form method="post" class="form-grid"><?=csrf_field()?><div class="field"><label>Shop category name</label><input name="name" placeholder="Mobile &amp; Electronics Shop" required></div><div class="field"><label>Category icon / logo path</label><input name="icon_path" placeholder="/uploads/categories/mobile.png"></div><div class="field"><label>Commission type</label><select name="commission_type"><option value="PERCENTAGE">Percentage based (%)</option><option value="FIXED">Fixed amount</option></select></div><div class="field"><label>Platform commission cut (%)</label><input name="platform_commission_rate" type="number" min="0" max="100" step="0.01" value="5" required></div><div class="field"><label>Customer cashback reward (%)</label><input name="customer_reward_rate" type="number" min="0" max="100" step="0.01" value="2" required></div><div class="field full"><p class="help">Working rule: assigned vendors inherit this category’s commission and customer reward configuration.</p><button class="btn">Save &amp; create category</button></div></form></section><section class="panel"><div class="panel-head"><h2>2. Saved shop categories &amp; commission directory</h2><span class="badge active">LIVE CATEGORIES</span></div><div class="table-wrap"><table><thead><tr><th>Category code</th><th>Category name &amp; icon</th><th>Commission type</th><th>Platform cut</th><th>Customer reward</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php foreach($rows as $row):?><tr><td><?=e('CAT_'.str_pad((string)$row['id'],3,'0',STR_PAD_LEFT))?></td><td><?php if($row['character_asset_url']):?><img src="<?=e($row['character_asset_url'])?>" alt="" style="width:22px;height:22px;object-fit:contain;vertical-align:middle"><?php endif?><strong><?=e($row['name'])?></strong></td><td><?=e($row['commission_type'])?></td><td><?=e(number_format((float)$row['platform_commission_rate'],2))?>%</td><td><?=e(number_format((float)$row['customer_reward_rate'],2))?>%</td><td><span class="badge <?=strtolower(e($row['status']))?>"><?=e($row['status'])?></span></td><td><a class="btn small secondary" href="<?=e(app_url('/admin/categories/edit.php?id='.$row['id']))?>">Edit</a></td></tr><?php endforeach?></tbody></table><?php if(!$rows):?><div class="empty">No shop categories configured.</div><?php endif?></div></section><?php require APP_ROOT.'/includes/footer.php';
